        @idFeriado         INT,
        @fecha             DATETIME,
        @motivo            VARCHAR(250),
        @fechaTexto        VARCHAR(20),
        @fechaNormalizada  VARCHAR(20),
        @idTexto           VARCHAR(20),
        @p1                INT,
        @p2                INT,
        @p3                INT;
    SET @Data = LTRIM(RTRIM(ISNULL(@Data, '')));

