            LTRIM(RTRIM(
                SUBSTRING(@Data, 1, @p1 - 1)
            ))
        );

    IF @accion = 'LISTAR'
    BEGIN

        SELECT
            CAST(idFeriado AS VARCHAR(20)) + '|' +
