            )
        ));
        SET @fechaNormalizada = REPLACE(@fechaTexto, '-', '');
        IF LEN(@fechaNormalizada) <> 8
           OR @fechaNormalizada LIKE '%[^0-9]%'
           OR ISDATE(@fechaNormalizada) = 0
