            (
                PersonalNombres,
                PersonalApellidos,
                AreaId,
                PersonalCodigo,
                PersonalNacimiento,
                PersonalIngreso,
                PersonalDNI,
                PersonalDireccion,
                PersonalTelefono,
                PersonalTelefonoAsi,
                PersonalEmail,
                PersonalSueldo,
                PersonalEstado,
                PersonalBajaFecha,
                PersonalRuc,
                PersonalImagen,
