CREATE PROCEDURE dbo.uspinsertarNotaBweb     @ListaOrden varchar(max) AS BEGIN     SET NOCOUNT ON;      DECLARE         @pos1 int,         @orden varchar(max),         @detalle varchar(max);      SET @pos1 = CHARINDEX('[', @ListaOrden, 1);      IF @pos1 <= 0     BEGIN         RAISERROR('Formato de orden invalido.', 16, 1);         RETURN;     END;      SET @orden = SUBSTRING(         @ListaOrden,         1,         @pos1 - 1     );      SET @detalle = SUBSTRING(         @ListaOrden,         @pos1 + 1,         LEN(@ListaOrden) - @pos1     );      DECLARE @campos TABLE     (         Pos int IDENTITY(1,1) NOT NULL,         Valor varchar(max) NULL     );      DECLARE         @start int,         @end int;      SET @start = 1;      WHILE @start <= LEN(@orden) + 1     BEGIN         SET @end = CHARINDEX('|', @orden, @start);          IF @end = 0             SET @end = LEN(@orden) + 1;          INSERT INTO @campos         (             Valor         )         VALUES         (             SUBSTRING(                 @orden,                 @start,                 @end - @start             )         );          SET @start = @end + 1;     END;      DECLARE         @NotaDocu varchar(60),         @ClienteId numeric(20),         @NotaUsuario varchar(60),         @NotaFormaPago varchar(60),         @NotaCondicion varchar(60),         @NotaDireccion varchar(max),         @CompaniaUbigeo varchar(250),          @NotaSubtotal decimal(18,2),         @NotaMovilidad decimal(18,2),         @NotaDescuento decimal(18,2),         @NotaTotal decimal(18,2),         @NotaAcuenta decimal(18,2),         @NotaSaldo decimal(18,2),         @NotaAdicional decimal(18,2),         @NotaTarjeta decimal(18,2),         @NotaPagar decimal(18,2),          @NotaEstado varchar(60),         @CompaniaId int,         @NotaEntrega varchar(40),         @NotaConcepto varchar(60),          @Serie varchar(60),         @Numero varchar(60),         @NotaGanancia decimal(18,2),          @Letra varchar(max),         @DocuAdicional decimal(18,2),         @DocuHash varchar(250),         @EstadoSunat varchar(80),         @DocuSubtotal decimal(18,2),         @DocuIGV decimal(18,2),          @UsuarioId int,         @NotaTransaccion varchar(250),         @Miembro varchar(300),         @CodigoCliente varchar(80),          @ICBPER decimal(18,2),         @DocuGravada decimal(18,2),          @ConceptoOBS varchar(80),         @EstadoOBS varchar(20),         @PV varchar(40),         @Image varchar(max),          @CodigoRes varchar(80),         @Responsable varchar(300),          @EntidadBancaria varchar(80),         @Efectivo decimal(18,2),         @Deposito decimal(18,2),         @NroOperacion varchar(80),          @ClienteRazon varchar(140),         @ClienteRuc varchar(40),         @ClienteDni varchar(40),         @DireccionFiscal varchar(max),          @TipoCodigo char(20),         @cod varchar(60),          @NotaId numeric(38),         @DocuId numeric(38);      SELECT @NotaDocu = Valor     FROM @campos     WHERE Pos = 1;      SELECT @ClienteId =         CONVERT(             numeric(20),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 2;      SELECT @NotaUsuario = Valor     FROM @campos     WHERE Pos = 3;      SELECT @NotaFormaPago = Valor     FROM @campos     WHERE Pos = 4;      SELECT @NotaCondicion = Valor     FROM @campos     WHERE Pos = 5;      SELECT @NotaDireccion = Valor     FROM @campos     WHERE Pos = 6;      SELECT @NotaSubtotal =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 7;      SELECT @NotaMovilidad =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 8;      SELECT @NotaDescuento =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 9;      SELECT @NotaTotal =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 10;      SELECT @NotaAcuenta =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 11;      SELECT @NotaSaldo =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 12;      SELECT @NotaAdicional =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 13;      SELECT @NotaTarjeta =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 14;      SELECT @NotaPagar =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 15;      SELECT @NotaEstado = Valor     FROM @campos     WHERE Pos = 16;      SELECT @CompaniaId =         CONVERT(             int,             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 17;      SELECT @NotaEntrega = Valor     FROM @campos     WHERE Pos = 18;      SELECT @NotaConcepto = Valor     FROM @campos     WHERE Pos = 19;      SELECT @Serie = Valor     FROM @campos     WHERE Pos = 20;      SELECT @Numero = Valor     FROM @campos     WHERE Pos = 21;      SELECT @NotaGanancia =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 22;      SELECT @Letra = Valor     FROM @campos     WHERE Pos = 23;      SELECT @DocuAdicional =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 24;      SELECT @DocuHash = Valor     FROM @campos     WHERE Pos = 25;      SELECT @EstadoSunat = Valor     FROM @campos     WHERE Pos = 26;      SELECT @DocuSubtotal =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 27;      SELECT @DocuIGV =         CONVERT(             decimal(18,2),             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 28;      SELECT @UsuarioId =         CONVERT(             int,             ISNULL(NULLIF(Valor, ''), '0')         )     FROM @campos     WHERE Pos = 29;
    SELECT @NotaTransaccion = Valor FROM @campos WHERE Pos = 30;
    SELECT @Miembro = Valor FROM @campos WHERE Pos = 31;
    SELECT @CodigoCliente = Valor FROM @campos WHERE Pos = 32;
    SELECT @ICBPER = CONVERT(decimal(18,2), ISNULL(NULLIF(Valor, ''), '0')) FROM @campos WHERE Pos = 33;
    SELECT @DocuGravada = CONVERT(decimal(18,2), ISNULL(NULLIF(Valor, ''), '0')) FROM @campos WHERE Pos = 34;
    SELECT @ConceptoOBS = Valor FROM @campos WHERE Pos = 35;
    SELECT @EstadoOBS = Valor FROM @campos WHERE Pos = 36;
    SELECT @PV = Valor FROM @campos WHERE Pos = 37;
    SELECT @Image = Valor FROM @campos WHERE Pos = 38;
    SELECT @CodigoRes = Valor FROM @campos WHERE Pos = 39;
    SELECT @Responsable = Valor FROM @campos WHERE Pos = 40;
    SELECT @EntidadBancaria = Valor FROM @campos WHERE Pos = 41;
    SELECT @Efectivo = CONVERT(decimal(18,2), ISNULL(NULLIF(Valor, ''), '0')) FROM @campos WHERE Pos = 42;
    SELECT @Deposito = CONVERT(decimal(18,2), ISNULL(NULLIF(Valor, ''), '0')) FROM @campos WHERE Pos = 43;
    SELECT @NroOperacion = Valor FROM @campos WHERE Pos = 44;

    /* DNX_VALIDACION_ASISTENCIA_FLAG */
    IF ISNULL
    (
        (
            SELECT CASE
                     WHEN MAX(CASE WHEN ISNULL(i.ValorNum, 1) <> 0 THEN 1 ELSE 0 END) = 0 THEN 0
                     ELSE 1
                   END
            FROM dbo.Usuarios AS u
            INNER JOIN dbo.Personal AS p ON p.PersonalId = u.PersonalId
            LEFT JOIN dbo.Indicador AS i
              ON i.CompaniaId = p.CompaniaId
             AND i.Descripcion = 'ASISTENCIA'
            WHERE u.UsuarioID = @UsuarioId
        ),
        1
    ) = 1
    AND NOT EXISTS
    (
        SELECT 1
        FROM dbo.Asistencia AS a
        INNER JOIN dbo.Usuarios AS u ON u.PersonalId = a.PersonalId
        WHERE u.UsuarioID = @UsuarioId
          AND a.Fecha = CONVERT(date, GETDATE())
    )
    BEGIN
        SELECT 'NO ASISTIO';
        RETURN;
