CREATE  PROCEDURE dbo.uspObtenerCajaActivaWEB
    @UsuarioId INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CajaId NUMERIC(38);

    SELECT TOP (1)
        @CajaId = CajaId
    FROM dbo.Caja
    WHERE UsuarioId = @UsuarioId
      AND CajaEstado = 'ACTIVO'
    ORDER BY CajaId DESC;

    IF ISNULL(@CajaId, 0) = 0
        RETURN;

    DECLARE
        @MontoInicial DECIMAL(18, 2),
        @Ingresos DECIMAL(18, 2),
        @Tarjeta DECIMAL(18, 2),
        @Depositos DECIMAL(18, 2),
        @Salidas DECIMAL(18, 2);

    SELECT
        @MontoInicial = ISNULL(MontoIniSOl, 0)
    FROM dbo.Caja
    WHERE CajaId = @CajaId;

    SELECT
        @Ingresos = ISNULL(SUM(ISNULL(Efectivo, 0)), 0),
        @Tarjeta = ISNULL(
            SUM(
                CASE
                    WHEN UPPER(ISNULL(NotaFormaPago, '')) LIKE '%TARJETA%'
                        THEN ISNULL(Deposito, 0)
                    ELSE 0
                END
            ),
            0
        ),
        @Depositos = ISNULL(
            SUM(
                CASE
                    WHEN UPPER(ISNULL(NotaFormaPago, '')) NOT LIKE '%TARJETA%'
                        THEN ISNULL(Deposito, 0)
                    ELSE 0
                END
            ),
            0
        )
    FROM dbo.NotaPedido
    WHERE CajaId = @CajaId
      AND ISNULL(NotaEstado, '') <> 'ANULADO';

    SELECT
        @Salidas = ISNULL(
            SUM(ISNULL(DetalleEfectivo, DetalleMonto)),
            0
        )
    FROM dbo.CajaDetalle
    WHERE CajaId = @CajaId
      AND DetalleMovimiento = 'SALIDA'
      AND ISNULL(NotaId, 0) = 0;

    SELECT
        CONVERT(BIGINT, c.CajaId) AS CajaId,
        CONVERT(VARCHAR(19), c.CajaFecha, 126) AS FechaApertura,
        ISNULL(c.MontoIniSOl, 0) AS MontoInicial,
        ISNULL(c.CajaEncargado, '') AS Encargado,
        ISNULL(c.CajaUsuario, '') AS Usuario,
        ISNULL(c.Observacion, '') AS Observacion,
        @Ingresos AS VentasEfectivo,
        @Tarjeta AS VentasTarjeta,
        @Depositos AS VentasDeposito,
        @Salidas AS Salidas,
        @MontoInicial + @Ingresos - @Salidas AS EfectivoEsperado
    FROM dbo.Caja c
    WHERE c.CajaId = @CajaId;

    SELECT
        Billete,
        ISNULL(Efectivo, 0) AS Cantidad
    FROM dbo.Monedas
    WHERE CajaId = @CajaId
    ORDER BY CONVERT(DECIMAL(18, 2), Billete) DESC;
END;

CREATE  PROCEDURE dbo.uspValidaCantCajas
    @CajaId NUMERIC(38, 0),
    @UsuarioId INT
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1
        FROM Caja WITH (UPDLOCK, HOLDLOCK)
        WHERE CajaEstado = 'ACTIVO'
          AND UsuarioId = @UsuarioId
          AND CajaId <> @CajaId
    )
    BEGIN
        SELECT 'USUARIO_ACTIVO';
        RETURN;
    END;

    IF (
        SELECT COUNT(*)
        FROM Caja WITH (UPDLOCK, HOLDLOCK)
        WHERE CajaEstado = 'ACTIVO'
          AND CajaId <> @CajaId
    ) >= 3
    BEGIN
        SELECT 'NO CERRO';
        RETURN;
    END;

    SELECT 'true';
END;

CREATE  PROCEDURE dbo.uspValidaCantCajasWeb
    @CajaId numeric(38, 0),
    @UsuarioId int
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CompaniaId int, @FlagCaja bit = 0;

    SELECT @CompaniaId = p.CompaniaId
      FROM dbo.Usuarios u
      INNER JOIN dbo.Personal p ON p.PersonalId = u.PersonalId
     WHERE u.UsuarioID = @UsuarioId;

    SELECT TOP (1) @FlagCaja = CONVERT(bit, ISNULL(i.ValorNum, 0))
      FROM dbo.Indicador i
     WHERE i.CompaniaId = @CompaniaId
       AND i.Descripcion = 'MULTIPLES_CAJAS'
     ORDER BY i.Id DESC;

    IF ISNULL(@FlagCaja, 0) = 1
    BEGIN
        SELECT 'true';
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
          FROM dbo.Caja c WITH (UPDLOCK, HOLDLOCK)
          INNER JOIN dbo.Usuarios u ON u.UsuarioID = c.UsuarioId
          INNER JOIN dbo.Personal p ON p.PersonalId = u.PersonalId
         WHERE c.CajaEstado = 'ACTIVO'
           AND p.CompaniaId = @CompaniaId
           AND c.CajaId <> @CajaId
    )
    BEGIN
        SELECT 'SOLO_UNA_CAJA';
        RETURN;
    END;

    SELECT 'true';
END;

CREATE PROCEDURE dbo.uspValidarArqueoCajaWEB
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FechaArqueo date = DATEADD(DAY, -1, CONVERT(date, GETDATE()));

    -- When yesterday is Sunday, the legacy rule checks the preceding Friday.
    IF DATEDIFF(DAY, CONVERT(date, '19000107', 112), @FechaArqueo) % 7 = 0
        SET @FechaArqueo = DATEADD(DAY, -2, @FechaArqueo);

    IF EXISTS
    (
        SELECT 1
          FROM dbo.ConteoMonedas
         WHERE FechaConteo >= @FechaArqueo
           AND FechaConteo < DATEADD(DAY, 1, @FechaArqueo)
    )
       OR EXISTS
    (
        SELECT 1
          FROM dbo.Feriados
         WHERE Fecha = @FechaArqueo
    )
    BEGIN
        SELECT 'true';
        RETURN;
    END;

    SELECT 'NO ARQUEO';
END;

CREATE  PROCEDURE dbo.uspValidarPagoVariosCajaFinalWEB
    @Fecha date
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
          FROM dbo.DocumentoVenta d
          INNER JOIN dbo.NotaPedido n ON n.NotaId = d.NotaId
         WHERE n.NotaCondicion = 'PAGO/VARIOS'
           AND n.NotaEstado <> 'CANCELADO'
           AND n.NotaEstado <> 'ANULADO'
           AND n.NotaFecha >= @Fecha
           AND n.NotaFecha < DATEADD(DAY, 1, @Fecha)
    )
    BEGIN
        SELECT 'PAGO/VARIOS';
        RETURN;
    END;

    SELECT 'true';
END;

